import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"25、【无妄】 震下乾上","description":"周易集注 - 25、【无妄】 震下乾上","frontmatter":{"title":"25、【无妄】 震下乾上","description":"周易集注 - 25、【无妄】 震下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/029.md","filePath":"zh/classics/jizhu/029.md"}'),h={name:"zh/classics/jizhu/029.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_25、【无妄】-震下乾上" tabindex="-1">25、【无妄】 震下乾上 <a class="header-anchor" href="#_25、【无妄】-震下乾上" aria-label="Permalink to “25、【无妄】 震下乾上”">​</a></h1><p>无妄者，至诚无虚妄也。《史记》作无所期望。盖惟本无妄，所以凡事尽其在我，而于吉凶祸福皆委之自然，未尝有所期望，所以无妄也。以天道言，实理之自然也。以圣人言，实心之自然也。故有正不正之分。盖震者动也，动以天为无妄，动以人则妄矣。《序卦》“复则不妄，故受之以无妄”，所以次复。</p><p>惟其无妄，所以不期望。若处心，未免于妄而匪正，则无道以致福。而妄欲徼福，非所谓无妄之福。有过以召灾，而妄欲见灾，非所谓无妄之灾。此皆未免容心于祸福之间，非所谓无妄也，岂不有眚。若真实无妄之人，则纯乎正理，祸福一付之天而无茍得幸免之心也。</p><p>《彖》曰：无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣?天命不祐，行矣哉?</p><p>本卦综大畜，二卦同体。文王综为一卦，故《杂卦》曰“大畜时也，无妄灾也”。刚自外来者，大畜上卦之艮来居无妄之下卦而为震也。刚自外来，作主于内，又性震动，又自外来，则动以人不动以天，非至诚无虚妄矣。所以有人之眚而不利有攸往也。内动而外健，故大亨。刚中而应，故正天命者，至诚乃天命之实理，反身而诚者也。若自外来，岂得为天命。</p><p>以卦综卦德卦体释卦辞。言文王卦辞元亨利贞之外，而又言其匪正有眚，不利有攸往者，以刚自外来而为主于内也。若本卦动而健，以刚中而应柔中，则大亨以正矣。大亨以正，实天之命也。天命实理，无一毫人欲之私，此文王卦辞所以言元亨也。若以外来者为主，则有人欲之私，非反身而诚，天命之实理即匪正矣。欲，往也，将何之哉，是以天命不祐，有眚而不利也。此所以文王卦辞言元亨而又利贞也。若旧注以刚自外来为自讼来，则非自外来，乃自内来矣。</p><h3 id="《象》曰-天下雷行-物与无妄。先王以茂对时育万物。" tabindex="-1">《象》曰：天下雷行，物与无妄。先王以茂对时育万物。 <a class="header-anchor" href="#《象》曰-天下雷行-物与无妄。先王以茂对时育万物。" aria-label="Permalink to “《象》曰：天下雷行，物与无妄。先王以茂对时育万物。”">​</a></h3><p>茂者盛也，物物皆对时而育之，所育者极其盛大，非止一物也，即如雷地豫之殷也。对时者，因雷发生，万物对其所育之时也，如孟春牺牲毋用牝之类是也。天下雷行，震动发生，一物各具太极，是物物而与之。无妄者，天道之自然也。茂对时育万物，撙节爱养，辅相裁成，使物物各遂其无妄之性者，圣人之当然也。</p><p>初九，无妄往，吉。</p><p>爻与彖辞不同者，爻以一爻之定体而言，彖以全体相综大畜而言。</p><p>九以阳刚之德居无妄之初，有所动，所谓动以天也。且应爻亦刚，无系恋之私，是一感一应，纯乎其诚矣，何吉如之。故占者往则吉。</p><h3 id="《象》曰-无妄之往-得志也。" tabindex="-1">《象》曰：无妄之往，得志也。 <a class="header-anchor" href="#《象》曰-无妄之往-得志也。" aria-label="Permalink to “《象》曰：无妄之往，得志也。”">​</a></h3><p>诚能动物，何往而不遂其心志。</p><p>六二，不耕获，不菑畬，则利有攸往。</p><p>耕者，春耕也。获者，秋敛也。菑者，田之一岁，垦而方成者。畬者，田之三岁垦而已熟者。农家始而耕，终而获，始而菑，终而畬。不耕获者，不方耕而即望其获也。不菑畬者，不方菑而即望其畬也。耕也，菑也，即明其道也。获也，畬也，即功也。曰“不耕获，不菑畬”，即明其道，不计其功也。观《小象》未富可见矣。若《程传》“不首造其事”，本义无所为于前，无所冀于后，将道理通讲空了，乃禅学也。吾儒圣人之学，进德修业，尽其理之当然，穷通得丧，听其天之自然，修身俟命，此正所谓无妄也。岂一点道理不进，空空寂寂，谓之无妄哉。初为地位，二为田，故九二曰见龙在田。震居东，二三皆阴土，水临土上，春耕之象也。震为禾稼，中爻艮为手，耒在手，获之象也。中爻巽，下卦震，上入下动，菑畬之象也，故禾耨取诸益。</p><p>六二柔顺中正，当无妄之时，无私意期望之心，故有不耕获，不菑畬之象。言虽于前无所望于后，占者必如此，则利有攸往矣。</p><h3 id="《象》曰-不耕获-未富也。" tabindex="-1">《象》曰：不耕获，未富也。 <a class="header-anchor" href="#《象》曰-不耕获-未富也。" aria-label="Permalink to “《象》曰：不耕获，未富也。”">​</a></h3><p>言未有富之心也。此富字虽曰未有此心，然亦本于象。盖巽为市利，小畜上体乃巽，《小象》曰：不独富也。此卦中爻巽曰未富者，未入巽之位也。</p><p>六三，无妄之灾，或系之牛，行人之得，邑人之灾。</p><p>本卦大象离，此爻又变为离，离为牛，牛之象也。中爻巽，为绳，又艮为鼻，绳系牛鼻之象也。震为足，行之象也。三为人位，人在震之大涂，行人之象也。三居坤土，得称邑，又居人位，邑人之象也。此爻居震动之极，牛失之象也。又变离错坎，坎为盗，亦牛失之象也。或者，设，或也。即，假如二字。假牛以明无妄之灾，乃六三也。即邑人也。</p><p>六三阴柔不正，故有此象。言或系牛于此，乃邑人之牛也。牛有所系，本不期望其走失，偶脱所系而为行人所得。邑人有失牛之灾，亦适然不幸耳，非自己有以致之，故为无妄之灾。即象而占可知矣。</p><h3 id="《象》曰-行人得牛-邑人灾也。" tabindex="-1">《象》曰：行人得牛，邑人灾也。 <a class="header-anchor" href="#《象》曰-行人得牛-邑人灾也。" aria-label="Permalink to “《象》曰：行人得牛，邑人灾也。”">​</a></h3><p>行人得牛而去，邑人不期望其失牛而失牛，故为无妄之灾。</p><p>九四，可贞，无咎。</p><p>可者，当也。九阳刚健体，其才亦可以有为者。但下无应与，无所系恋而无妄者也。占者得此，但可守此无妄之正道，即无咎矣。若妄动，又不免有咎也。</p><h3 id="《象》曰-可贞无咎-固有之也。" tabindex="-1">《象》曰：可贞无咎，固有之也。 <a class="header-anchor" href="#《象》曰-可贞无咎-固有之也。" aria-label="Permalink to “《象》曰：可贞无咎，固有之也。”">​</a></h3><p>固有者，本有也。无应与，则无系恋而无妄，则无妄乃九四之本有也。</p><p>九五，无妄之疾，勿药，有喜。</p><p>五变则中爻成坎，坎为心病，疾之象也。中爻巽木，艮石药之象也。中爻巽，综兑，悦喜之象也。意外之变，虽圣人亦不能无，但圣人廓然大公，物来顺应，来则照而去不留，无意必固我之私，是以意外之来，犹无妄之疾耳。如舜之有苗，周公之流言，皆无妄之疾也。诞敷文教而有苗格公孙硕肤德音不瑕，大舜周公之疾不药而自愈矣。</p><p>九五阳刚中正，以居尊位而下应，亦中正无妄之至也。如是而犹有疾，乃无妄之疾，不当得而得者，故勿药自愈，其象占如此。</p><h3 id="《象》曰-无妄之药-不可试也。" tabindex="-1">《象》曰：无妄之药，不可试也。 <a class="header-anchor" href="#《象》曰-无妄之药-不可试也。" aria-label="Permalink to “《象》曰：无妄之药，不可试也。”">​</a></h3><p>试者，少尝之也。无妄之疾，勿药者，以无妄之药，不可尝也。若尝而攻治，则反为妄而生疾矣。故不可轻试其药，止可听其自愈。</p><p>上九，无妄行，有眚，无攸利。</p><p>下应震，足行之象也。九非有妄，但时位穷极，不可行耳。故其象占如此。</p><h3 id="《象》曰-无妄之行-穷之灾也。" tabindex="-1">《象》曰：无妄之行，穷之灾也。 <a class="header-anchor" href="#《象》曰-无妄之行-穷之灾也。" aria-label="Permalink to “《象》曰：无妄之行，穷之灾也。”">​</a></h3><p>无妄未有不可行者，以时位耳。与亢龙同，故二小象亦同。</p>',36)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
